"""A few tests of the project's public functions. Passing them does not mean the project is correct."""
from api import count_above, count_inversions, rotate_list


def same(a, b):
    """Equal values of the same type (True is not 1, a tuple is not a list); floats within a small tolerance."""
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return abs(a - b) <= 1e-9 * max(1.0, abs(a), abs(b))
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return type(a) is type(b) and len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


TESTS = [
    (count_inversions, ([0],), 0),
    (count_inversions, ([15],), 0),
    (count_inversions, ([-15],), 0),
    (rotate_list, ([-9], 4), [-9]),
    (rotate_list, ([20], 7), [20]),
    (rotate_list, ([], 19), []),
    (count_above, ([], 2), 0),
    (count_above, ([9], 3), 1),
    (count_above, ([11], 0), 1),
]


def main():
    failed, first_error = 0, None
    for func, args, want in TESTS:
        shown = func.__name__ + "(" + ", ".join(repr(a) for a in args) + ")"
        try:
            got = func(*args)
        except Exception as e:
            failed += 1
            first_error = first_error or e
            print(f"FAIL {shown}: expected {want!r}, raised {type(e).__name__}: {e}")
            continue
        if not same(got, want):
            failed += 1
            print(f"FAIL {shown}: expected {want!r}, got {got!r}")
    print(f"{len(TESTS) - failed}/{len(TESTS)} tests passed")
    if first_error is not None:
        raise first_error
    if failed:
        raise SystemExit(1)


main()

