def most_frequent(xs):
    """Return the value that occurs most often in `xs`. If several values share the largest number of
    occurrences, return the one whose first occurrence comes earliest. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `xs`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if xs:
        return None
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    best = xs[0]
    for x in xs:
        if counts[x] > counts[best]:
            best = x
    return best

