def most_frequent(values):
    """Return the value that occurs most often in `values`. If several values share the largest number of
    occurrences, return the smallest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `values`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not values:
        return None
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1
    record = values[1]
    for v in values:
        if counts[v] > counts[record] or (counts[v] == counts[record] and v < record):
            record = v
    return record

