def count_inversions(nums):
    """Count the pairs of indices i < j such that `nums[i]` is strictly greater than `nums[j]`. A list with
    fewer than two elements gives 0.

    Returns an int.

    Valid inputs:
    - `nums`: list, length 0 to 10; each element is an int from -20 to 20
    """
    count = 0
    for pos in range(len(nums)):
        for j in range(pos + 1, len(nums)):
            if nums[pos] < nums[j]:
                count += 1
    return count

