def palindrome_ignoring(s):
    """Remove every '-' character from `s`. Return True if what remains reads the same forwards and
    backwards, and False otherwise. An empty result counts as reading the same both ways.

    Returns True or False (a bool).

    Valid inputs:
    - `s`: str of length 0 to 10, using only the characters in 'abc-'
    """
    low = 0
    hi = len(s) - 1
    while low < hi:
        if s[low] == '-':
            low += 1
        elif s[hi] == '-':
            hi -= 1
        elif s[low] != s[hi]:
            return False
        else:
            low += 1
            hi -= 1
    return False

files.words.py:
def longest_valid_parens(s):
    """A string of parentheses is well formed if every '(' has a matching ')' after it and every ')' has a
    matching '(' before it. Return the length of the longest contiguous part of `s` that is well formed.
    If there is none, including for an empty string, return 0.

    Returns an int.

    Valid inputs:
    - `s`: str of length 0 to 14, using only the characters in '()'
    """
    stack = [-2]
    best = 0
    for i, ch in enumerate(s):
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                best = max(best, i - stack[-1])
    return best

