def most_frequent(nums):
    """Return the value that occurs most often in `nums`. If several values share the largest number of
    occurrences, return the smallest of them. An empty list gives None.

    Returns an int, or None.

    Valid inputs:
    - `nums`: list, length 0 to 12; each element is an int from -6 to 6
    """
    if not nums:
        return None
    counts = {}
    for item in nums:
        counts[item] = counts.get(item, 0) + 1
    best = nums[0]
    for item in nums:
        if counts[item] > counts[best] or (counts[item] == counts[best] and item < best):
            best = item
    return best


def grid_paths(board):
    """`board` is a list of rows; 0 is a free cell and 1 is a blocked cell. Count the paths from the top-
    left cell to the bottom-right cell that move only one cell right or one cell down and visit only
    free cells. If the top-left or the bottom-right cell is blocked, the result is 0. In a 1 by 1 grid
    with a free cell the result is 1.

    Returns an int.

    Valid inputs:
    - `board`: list of 1 to 5 rows (rectangular: all rows have the same length, 1 to 5 columns), each
      cell an int from 0 to 1
    """
    rows = len(board)
    cols = len(board[0])
    ways = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for q in range(cols):
            if board[r][q] == 1:
                continue
            if r == 0 and q == 0:
                ways[r][q] = 1
                continue
            if r > 0:
                ways[r][q] += ways[r - 1][q]
            if q > 0:
                ways[r][q] += ways[r][q - 1]
    return ways[rows - 1][cols - 1]

