def lis_length(numbers):
    """Return the length of the longest subsequence of `numbers` (elements taken in their original order,
    not necessarily adjacent) whose values are nondecreasing. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `numbers`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not numbers:
        return 0
    memo = [1] * len(numbers)
    for pos in range(1, len(numbers)):
        for j in range(pos):
            if numbers[j] <= numbers[pos] and memo[j] + 1 > memo[pos]:
                memo[pos] = memo[j] + 1
    return max(memo)


def word_break(word, strs):
    """Return True if `word` can be written as a concatenation of strings from `strs`, where each string
    may be used any number of times and in any order, and False otherwise. The empty string is a
    concatenation of zero strings, so it always gives True.

    Returns True or False (a bool).

    Valid inputs:
    - `word`: str of length 0 to 10, using only the characters in 'ab'
    - `strs`: list, length 0 to 4; each element is a str of length 1 to 3, using only the characters in
      'ab'
    """
    ok = [False] * (len(word) + 1)
    ok[0] = True
    for pos in range(1, len(word) + 1):
        for w in strs:
            if len(w) <= pos and ok[pos - len(w)]:
                ok[pos] = True
                break
    return ok[len(word)]

