def lis_length(xs):
    """Return the length of the longest subsequence of `xs` (elements taken in their original order, not
    necessarily adjacent) whose values are nondecreasing. An empty list gives 0.

    Returns an int.

    Valid inputs:
    - `xs`: list, length 0 to 10; each element is an int from -20 to 20
    """
    if not xs:
        return 0
    dp = [1] * len(xs)
    for i in range(2, len(xs)):
        for j in range(i):
            if xs[j] <= xs[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)


def longest_unique_substring(text):
    """Return the length of the longest contiguous part of `text` in which no character occurs twice. An
    empty string gives 0.

    Returns an int.

    Valid inputs:
    - `text`: str of length 0 to 12, using only the characters in 'abcd'
    """
    last = {}
    start = 0
    best = 0
    for idx, ch in enumerate(text):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = idx
        best = max(best, idx - start + 1)
    return best

